//! Dash Core's test vectors and loaders with Core's harness semantics.
//!
//! The data lives in `test-vectors/core/<commit>/` (verbatim copies of Core's files, plus
//! `transcribed/` and `golden/` sets generated by instrumented Core code, each documented in the
//! directory's `PROVENANCE.md`). This crate is a leaf: it depends on nothing in the workspace, so
//! any crate can use it as a dev-dependency without creating a cycle.
//!
//! See `test-vectors/README.md` for how to update the pin and `PROVENANCE.md` for the quirks of
//! Core's harness that these loaders deliberately do not reproduce.

pub mod cases;
pub mod flags;
pub mod golden;
pub mod hex;
pub mod script;
pub mod script_error;
pub mod univalue;

use std::path::{Path, PathBuf};

/// The Dash Core commit the checked-in vectors were taken from (`v24.0.0-rc.3`).
pub const CORE_COMMIT: &str = "0364ed626ec2eaa518bf1ae4a0566ce638c7fe18";

/// Directory name under `test-vectors/core/` (the first 12 hex digits of [`CORE_COMMIT`]).
pub const CORE_DIR: &str = "0364ed626ec2";

/// `test-vectors/core/<commit>/` for the pinned commit.
pub fn core_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("core").join(CORE_DIR)
}

fn read_path(path: PathBuf) -> Vec<u8> {
    std::fs::read(&path)
        .unwrap_or_else(|e| panic!("cannot read vector file {}: {e}", path.display()))
}

/// Reads a vector file relative to [`core_dir`], e.g. `"src/test/data/script_tests.json"`.
///
/// Panics with the full path if the file is missing: a vector that silently fails to load would
/// turn a conformance test into a no-op.
pub fn read_core_file(relative: &str) -> Vec<u8> {
    read_path(core_dir().join(relative))
}

/// [`read_core_file`] as UTF-8 text.
pub fn read_core_text(relative: &str) -> String {
    String::from_utf8(read_core_file(relative))
        .unwrap_or_else(|e| panic!("vector file {relative} is not UTF-8: {e}"))
}

/// Reads a file relative to `test-vectors/` itself (for the `golden/` fixtures, which are not tied
/// to a Core source tree layout).
pub fn read_vector_file(relative: &str) -> Vec<u8> {
    read_path(Path::new(env!("CARGO_MANIFEST_DIR")).join(relative))
}

/// [`read_vector_file`] as UTF-8 text.
pub fn read_vector_text(relative: &str) -> String {
    String::from_utf8(read_vector_file(relative))
        .unwrap_or_else(|e| panic!("vector file {relative} is not UTF-8: {e}"))
}
